ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    errors: [{
        errorCode: vars.vHttpStatusCode,
        title: error.errorType.identifier,
        errorMessage: [error.description replace('"')  with('')],
        timeStamp: now(),
        domain: app.name,
        traceId: correlationId

    }]
}
